}

input.new_string:
export async function listNotifications(
  actor: Actor,
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  assertOrgScope(actor, input.orgId);
  assertOwnInbox(actor, "notification:read", input.orgId, input.recipientId);
  return notificationRepo.listNotifications(input);
}

export async function markRead(
  actor: Actor,
  input: MarkNotificationReadInput,
): Promise<Notification> {
  assertOrgScope(actor, input.orgId);
  const existing = await notificationRepo.findNotificationById(
    input.orgId,
    input.notificationId,
  );
  if (!existing) {
    return notificationRepo.markRead(
      input.orgId,
      input.notificationId,
      toIsoTimestamp(new Date()),
    );
  }
  assertOwnInbox(actor, "notification:manage", input.orgId, existing.recipientId);
  return notificationRepo.markRead(
    input.orgId,
    input.notificationId,
    toIsoTimestamp(new Date()),
  );
}

export async function markAllRead(
  actor: Actor,
  orgId: OrgId,
): Promise<number> {
  assertOrgScope(actor, orgId);
  assertOwnInbox(actor, "notification:manage", orgId, actor.userId);
  return notificationRepo.markAllRead(
    orgId,
    actor.userId,
    toIsoTimestamp(new Date()),
  );
}

export async function updatePreference(
  actor: Actor,
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  assertOrgScope(actor, input.orgId);
  assertOwnInbox(actor, "notification:manage", input.orgId, input.userId);
  return preferenceRepo.upsertPreference(input);
}

/**
 * An inbox and its settings belong to one member. Role never widens that:
 * an owner reading or editing someone else's alerts is refused.
 */
function assertOwnInbox(
  actor: Actor,
  action: Extract<PermissionAction, "notification:read" | "notification:manage">,
  orgId: OrgId,
  recipientId: UserId,
): void {
  if (recipientId !== actor.userId) {
    throw new PermissionDeniedError(action, {
      allowed: false,
      action,
      resourceKind: "notification",
      reason: "denied_by_role",
    });
  }
  assertCan(actor, action, notificationResource(orgId, recipientId));
}

