async function hrefFor(
  org: Organization | null,
  kind: SearchSubjectKind,
  subjectId: string,
): Promise<string> {
  if (!org) return "/";

  switch (kind) {
    case "issue":
      return issuePageHref(org, subjectId as IssueId);
    case "comment": {
      const comment = await commentRepo.findCommentById(
        org.id,
        subjectId as CommentId,
      );
      if (!comment) return `/${org.slug}`;
      return issuePageHref(org, comment.issueId);
    }
    case "project": {
      const project = await projectRepo.findProjectById(
        org.id,
        subjectId as ProjectId,
      );
      return project
        ? projectPath(org.slug, project.slug)
        : projectPath(org.slug, subjectId);
    }
  }
}

async function issuePageHref(
  org: Organization,
  issueId: IssueId,
): Promise<string> {
  const issue = await issueRepo.findIssueById(org.id, issueId);
