/**
 * True when this recipient already has an unread alert of `kind` with this
 * title. Plan-limit refusals use a stable title per resource so a repeat
 * refusal adds nothing until the existing alert is read.
 */
export async function hasUnreadWithTitle(
  orgId: OrgId,
  recipientId: UserId,
  kind: NotificationKind,
  title: string,
): Promise<boolean> {
  const row = getDb()
    .select({ id: notifications.id })
    .from(notifications)
    .where(
      and(
        orgPredicate(notifications.orgId, orgId),
        eq(notifications.recipientId, recipientId),
        eq(notifications.kind, kind),
        eq(notifications.title, title),
        isNull(notifications.readAt),
      ),
    )
    .get();

  return row !== undefined;
}

